package com.ecommerce.cart.service;
import com.ecommerce.cart.model.*; import com.ecommerce.cart.repository.CartRepository; import com.ecommerce.cart.dto.ItemRequest; import com.fasterxml.jackson.databind.JsonNode; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.web.server.ResponseStatusException; import java.time.Instant; import java.util.*;
@Service public class CartService {private final CartRepository repo;private final ProductClient products;public CartService(CartRepository r,ProductClient p){repo=r;products=p;}public Map<String,Object> view(String uid){Cart c=repo.findByUserId(uid).orElseGet(()->new Cart(uid));List<Map<String,Object>> out=new ArrayList<>();double total=0;for(Item i:c.getItems()){JsonNode p=products.get(i.getProductId());double price=p.path("price").asDouble(0);double line=price*i.getQuantity();total+=line;Map<String,Object> row=new LinkedHashMap<>();row.put("productId",i.getProductId());row.put("name",p.path("name").asText(p.path("title").asText("Product")));row.put("price",price);row.put("imageUrl",p.path("imageUrl").asText(null));row.put("available",p.path("available").asBoolean(true));row.put("quantity",i.getQuantity());row.put("lineTotal",line);out.add(row);}return Map.of("userId",uid,"items",out,"total",total);}public Cart add(String uid,ItemRequest req){products.get(req.getProductId());Cart c=repo.findByUserId(uid).orElseGet(()->new Cart(uid));Item i=c.getItems().stream().filter(x->x.getProductId().equals(req.getProductId())).findFirst().orElse(null);if(i==null)c.getItems().add(new Item(req.getProductId(),req.getQuantity()));else {long q=(long)i.getQuantity()+req.getQuantity();if(q>Integer.MAX_VALUE)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Quantity too large");i.setQuantity((int)q);}c.setUpdatedAt(Instant.now());return repo.save(c);}public Cart update(String uid,String pid,int q){Cart c=repo.findByUserId(uid).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Cart not found"));Item i=c.getItems().stream().filter(x->x.getProductId().equals(pid)).findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Item not found"));i.setQuantity(q);c.setUpdatedAt(Instant.now());return repo.save(c);}public Cart remove(String uid,String pid){Cart c=repo.findByUserId(uid).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Cart not found"));if(!c.getItems().removeIf(x->x.getProductId().equals(pid)))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Item not found");c.setUpdatedAt(Instant.now());return repo.save(c);}public void clear(String uid){repo.deleteByUserId(uid);}}